"""Receive WLED UDP debug output using Python's standard library."""

# AI: below section was generated by an AI
import argparse
import socket
import sys


def main():
    """Listen until Ctrl+C, optionally accepting only the specified ESP address."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--port", type=int, default=7868)
    parser.add_argument("--esp", help="Only display packets from this ESP IPv4 address")
    args = parser.parse_args()
    if not 1 <= args.port <= 65535:
        parser.error("port must be between 1 and 65535")
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as listener:
        listener.bind(("0.0.0.0", args.port))
        listener.settimeout(0.5)  # Let Windows process Ctrl+C while no packets arrive.
        print(f"Listening for WLED logs on UDP {args.port}. Ctrl+C exits.", flush=True)
        try:
            while True:
                try:
                    data, sender = listener.recvfrom(65535)
                except socket.timeout:
                    continue
                if args.esp and sender[0] != args.esp:
                    continue
                sys.stdout.write(data.decode("utf-8", errors="replace"))
                sys.stdout.flush()
        except KeyboardInterrupt:
            pass


if __name__ == "__main__":
    main()
# AI: end
